package config;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Regression test to verify that the native-image resource-config.json
 * includes all required shader files in the "globs" section.
 *
 * When the "globs" section is present, every javafx.graphics shader
 * referenced in "resources.includes" must also appear in "globs".
 * Previously, DrawRoundRect_Color.frag was missing from globs,
 * which would cause rendering failures at native-image runtime.
 */
class ResourceConfigConsistencyTest {

    @Test
    void globsSectionMustContainDrawRoundRectColorFragmentShader() throws IOException {
        // Read the resource-config.json from resources
        InputStream is = getClass().getClassLoader()
                .getResourceAsStream("META-INF/native-image/resource-config.json");
        assertNotNull(is, "resource-config.json should exist on classpath");

        String jsonStr = new String(is.readAllBytes(), StandardCharsets.UTF_8);
        JsonObject root = JsonParser.parseString(jsonStr).getAsJsonObject();

        JsonObject resources = root.getAsJsonObject("resources");
        // globs is at root level, not inside resources
        JsonElement globsElement = root.get("globs");

        // If globs section doesn't exist, the old format was used (only includes).
        // In that case, nothing to verify - skip.
        if (globsElement == null || globsElement.isJsonNull()) {
            // Old format without globs - nothing to check
            return;
        }
        JsonArray globs = globsElement.getAsJsonArray();

        // Collect all glob patterns for javafx.graphics module
        Set<String> globPaths = new HashSet<>();
        for (JsonElement entry : globs) {
            JsonObject obj = entry.getAsJsonObject();
            if (obj.has("module") && obj.has("glob")) {
                String module = obj.get("module").getAsString();
                String glob = obj.get("glob").getAsString();
                if ("javafx.graphics".equals(module)) {
                    globPaths.add(glob);
                }
            }
        }

        // DrawRoundRect_Color.frag must be present in globs since it's a required
        // shader used by JavaFX for rendering rounded rectangles.
        // It has a corresponding loader (DrawRoundRect_Color_Loader) in reflect-config.json
        // and is referenced in the includes section.
        String expectedShader = "com/sun/prism/es2/glsl/DrawRoundRect_Color.frag";
        assertTrue(globPaths.contains(expectedShader),
                "resource-config.json 'globs' section is missing '" + expectedShader
                + "' which is required for rendering rounded rectangles at native-image runtime");
    }

    @Test
    void globsSectionMustBeConsistentWithIncludesForJavafxGraphicsShaders() throws IOException {
        InputStream is = getClass().getClassLoader()
                .getResourceAsStream("META-INF/native-image/resource-config.json");
        assertNotNull(is, "resource-config.json should exist on classpath");

        String jsonStr = new String(is.readAllBytes(), StandardCharsets.UTF_8);
        JsonObject root = JsonParser.parseString(jsonStr).getAsJsonObject();

        JsonObject resources = root.getAsJsonObject("resources");
        // globs is at root level, not inside resources
        JsonElement globsElement = root.get("globs");

        // If globs section doesn't exist, skip
        if (globsElement == null || globsElement.isJsonNull()) {
            return;
        }
        JsonArray globs = globsElement.getAsJsonArray();

        // Collect all javafx.graphics globs
        Set<String> globPaths = new HashSet<>();
        for (JsonElement entry : globs) {
            JsonObject obj = entry.getAsJsonObject();
            if (obj.has("module") && obj.has("glob")) {
                String module = obj.get("module").getAsString();
                String glob = obj.get("glob").getAsString();
                if ("javafx.graphics".equals(module)) {
                    globPaths.add(glob);
                }
            }
        }

        // Collect all javafx.graphics shaders from includes
        JsonArray includes = resources.getAsJsonArray("includes");
        Set<String> missingFromGlobs = new HashSet<>();
        for (JsonElement entry : includes) {
            JsonObject obj = entry.getAsJsonObject();
            String pattern = obj.get("pattern").getAsString();
            // Pattern format: "javafx.graphics:\\Qcom/sun/prism/es2/glsl/DrawRoundRect_Color.frag\\E"
            if (pattern.startsWith("javafx.graphics:\\Q")) {
                // Extract the path from the pattern
                String path = pattern.substring("javafx.graphics:\\Q".length());
                if (path.endsWith("\\E")) {
                    path = path.substring(0, path.length() - 2);
                }
                // Check if this shader is a .frag file
                if (path.endsWith(".frag")) {
                    if (!globPaths.contains(path)) {
                        missingFromGlobs.add(path);
                    }
                }
            }
        }

        if (!missingFromGlobs.isEmpty()) {
            fail("resource-config.json 'globs' section is missing the following "
                    + "javafx.graphics shaders that are in 'includes': " + missingFromGlobs);
        }
    }
}

package nativeimage;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import org.junit.jupiter.api.Test;

import java.io.InputStream;
import java.util.Objects;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Validates that the GraalVM native-image resource-config.json bundles section
 * includes the default/base locale ("") for key JavaFX/XML ResourceBundles.
 *
 * The empty string "" locale represents the base properties file (e.g.
 * QuantumMessagesBundle.properties without any locale suffix). Without it,
 * the native image cannot fall back to the default locale when running with
 * a non-en-US locale, causing missing UI strings.
 */
class ResourceConfigBundlesTest {

    private static final String CONFIG_PATH =
        "/META-INF/native-image/resource-config.json";

    private static final String[] KEY_BUNDLES = {
        "com.sun.javafx.tk.quantum.QuantumMessagesBundle",
        "com.sun.org.apache.xml.internal.serializer.XMLEntities",
        "com/sun/javafx/scene/control/skin/resources/controls"
    };

    @Test
    void bundlesMustIncludeDefaultBaseLocaleEmptyString() throws Exception {
        InputStream is = Objects.requireNonNull(
            getClass().getResourceAsStream(CONFIG_PATH),
            "resource-config.json not found on classpath at " + CONFIG_PATH
        );

        Gson gson = new Gson();
        JsonObject config = gson.fromJson(
            new java.io.BufferedReader(new java.io.InputStreamReader(is)),
            JsonObject.class
        );
        JsonArray bundles = config.getAsJsonArray("bundles");
        assertNotNull(bundles, "bundles section missing in resource-config.json");

        for (String bundleName : KEY_BUNDLES) {
            JsonObject bundle = findBundle(bundles, bundleName);
            assertNotNull(bundle, "Bundle not found: " + bundleName);

            JsonArray locales = bundle.getAsJsonArray("locales");
            assertNotNull(locales, "locales array missing for bundle: " + bundleName);

            JsonElement emptyStringLocale = new com.google.gson.JsonPrimitive("");
            assertTrue(
                locales.contains(emptyStringLocale),
                "Bundle '" + bundleName + "' must include default locale '' (empty string) for fallback. Locales: " + locales
            );
        }
    }

    private JsonObject findBundle(JsonArray bundles, String name) {
        for (var elem : bundles) {
            JsonObject obj = elem.getAsJsonObject();
            if (obj.has("name") && obj.get("name").getAsString().equals(name)) {
                return obj;
            }
        }
        return null;
    }
}

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.fail;

/**
 * Tests that resource-config.json keeps its {@code includes} (deprecated pattern format)
 * consistent with {@code globs} (new format used by GraalVM 23+).
 * <p>
 * Every entry in {@code includes} that targets a specific module (e.g. {@code javafx.graphics:…})
 * must have a matching entry in {@code globs} so GraalVM native-image builds still ship the
 * resource when the deprecated "includes" section is ignored.
 */
class ResourceConfigConsistencyTest {

    @Test
    void everyModuleIncludeMustHaveAGlobEntry() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        try (InputStream is = getClass().getClassLoader()
                .getResourceAsStream("META-INF/native-image/resource-config.json")) {
            if (is == null) {
                fail("resource-config.json not found on classpath");
            }
            JsonNode root = mapper.readTree(is);

            JsonNode resources = root.get("resources");
            if (resources == null) fail("no 'resources' key in resource-config.json");

            JsonNode includes = resources.get("includes");
            JsonNode globs = resources.get("globs");
            if (globs == null) {
                globs = root.get("globs");  // some configs place globs at root level
            }

            // Collect module:resource pairs from the includes section
            List<String> includePairs = new ArrayList<>();
            if (includes != null && includes.isArray()) {
                for (JsonNode inc : includes) {
                    String pattern = inc.get("pattern").asText();
                    // Pattern format: "module:\Qpath\E" or just "\Qpath\E"
                    int colonQIdx = pattern.indexOf(":\\Q");
                    if (colonQIdx < 0) continue; // no module prefix
                    String module = pattern.substring(0, colonQIdx);
                    String resource = pattern.substring(colonQIdx + 3).replace("\\E", "");
                    if (resource.isEmpty()) continue;
                    includePairs.add(module + ":" + resource);
                }
            }

            // Collect module:resource pairs from the globs section
            List<String> globPairs = new ArrayList<>();
            if (globs != null && globs.isArray()) {
                for (JsonNode g : globs) {
                    JsonNode moduleNode = g.get("module");
                    JsonNode globNode = g.get("glob");
                    if (moduleNode != null && globNode != null) {
                        globPairs.add(moduleNode.asText() + ":" + globNode.asText());
                    }
                }
            }

            // Every include entry that has a module prefix must also appear in globs
            List<String> missing = new ArrayList<>();
            for (String pair : includePairs) {
                if (!globPairs.contains(pair)) {
                    missing.add(pair);
                }
            }

            assertFalse(missing.isEmpty() == false || missing.isEmpty(),
                    "Missing globs for includes entries:\n  " + String.join("\n  ", missing)
                    + "\nGraalVM 23+ uses the 'globs' section; without a matching glob, the\n"
                    + "resource will be excluded from the native image at runtime.");
        }
    }
}
